SET SERVEROUTPUT ON;
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;
PROMPT ============================================================
PROMPT DPS2 Phase 11L - Wave C Steps 09-13 DB Verifier
PROMPT ============================================================
DECLARE
 p NUMBER:=0; f NUMBER:=0; v NUMBER;
 PROCEDURE chk(label VARCHAR2,ok BOOLEAN) IS BEGIN IF ok THEN p:=p+1;DBMS_OUTPUT.PUT_LINE('PASS | '||label);ELSE f:=f+1;DBMS_OUTPUT.PUT_LINE('FAIL | '||label);END IF; END;
 FUNCTION tab(t VARCHAR2) RETURN BOOLEAN IS n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='DPS2' AND TABLE_NAME=UPPER(t);RETURN n>0;END;
 FUNCTION seq_ahead(s VARCHAR2,t VARCHAR2,pk VARCHAR2) RETURN BOOLEAN IS n NUMBER; m NUMBER; BEGIN EXECUTE IMMEDIATE 'SELECT DPS2.'||s||'.NEXTVAL FROM DUAL' INTO n; EXECUTE IMMEDIATE 'SELECT NVL(MAX('||pk||'),0) FROM DPS2.'||t INTO m; RETURN n>m; END;
BEGIN
  chk('Step09 inquiry exists',tab('DEPOSIT_ACCOUNT_INQUIRY')); chk('Step09 confirmation exists',tab('DEPOSIT_ACCOUNT_CONFIRMATION')); chk('Step09 notification preference exists',tab('DEPOSIT_ACCOUNT_NOTIFICATION_PREFERENCE')); chk('Step09 notification event exists',tab('DEPOSIT_ACCOUNT_NOTIFICATION_EVENT')); chk('Step09 API access exists',tab('DEPOSIT_ACCOUNT_API_ACCESS'));
  chk('Step10 signature rule exists',tab('DEPOSIT_ACCOUNT_SIGNATURE_RULE')); chk('Step10 delegation exists',tab('DEPOSIT_ACCOUNT_DELEGATION')); chk('Step10 authorized user exists',tab('DEPOSIT_ACCOUNT_AUTHORIZED_USER')); chk('Step10 beneficiary exists',tab('DEPOSIT_ACCOUNT_BENEFICIARY')); chk('Step10 payment instrument exists',tab('DEPOSIT_ACCOUNT_PAYMENT_INSTRUMENT'));
  chk('Step11 regulatory restriction exists',tab('DEPOSIT_ACCOUNT_REGULATORY_RESTRICTION')); chk('Step11 compliance evaluation exists',tab('DEPOSIT_COMPLIANCE_EVALUATION'));
  chk('Step12 pricing override exists',tab('DEPOSIT_ACCOUNT_PRICING_OVERRIDE')); chk('Step12 fee assessment exists',tab('DEPOSIT_FEE_ASSESSMENT')); chk('Step12 profitability exists',tab('DEPOSIT_PROFITABILITY_SNAPSHOT'));
  chk('Step13 tax exemption exists',tab('DEPOSIT_TAX_EXEMPTION')); chk('Step13 tax calculation exists',tab('DEPOSIT_TAX_CALCULATION')); chk('Step13 tax certificate exists',tab('DEPOSIT_TAX_CERTIFICATE'));
  chk('inquiry sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_INQUIRY','DEPOSIT_ACCOUNT_INQUIRY','ACCOUNT_INQUIRY_ID')); chk('confirmation sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_CONFIRMATION','DEPOSIT_ACCOUNT_CONFIRMATION','ACCOUNT_CONFIRMATION_ID')); chk('notification preference sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_NOTIFICATION_PREFERENCE','DEPOSIT_ACCOUNT_NOTIFICATION_PREFERENCE','NOTIFICATION_PREFERENCE_ID')); chk('API access sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_API_ACCESS','DEPOSIT_ACCOUNT_API_ACCESS','ACCOUNT_API_ACCESS_ID'));
  chk('signature rule sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_SIGNATURE_RULE','DEPOSIT_ACCOUNT_SIGNATURE_RULE','ACCOUNT_SIGNATURE_RULE_ID')); chk('authorized user sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_AUTHORIZED_USER','DEPOSIT_ACCOUNT_AUTHORIZED_USER','ACCOUNT_AUTHORIZED_USER_ID')); chk('beneficiary sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_BENEFICIARY','DEPOSIT_ACCOUNT_BENEFICIARY','ACCOUNT_BENEFICIARY_ID')); chk('payment instrument sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_PAYMENT_INSTRUMENT','DEPOSIT_ACCOUNT_PAYMENT_INSTRUMENT','ACCOUNT_PAYMENT_INSTRUMENT_ID'));
  chk('regulatory restriction sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_REGULATORY_RESTRICTION','DEPOSIT_ACCOUNT_REGULATORY_RESTRICTION','ACCOUNT_REG_RESTRICTION_ID')); chk('compliance evaluation sequence ahead',seq_ahead('SEQ_DEPOSIT_COMPLIANCE_EVALUATION','DEPOSIT_COMPLIANCE_EVALUATION','COMPLIANCE_EVALUATION_ID')); chk('pricing override sequence ahead',seq_ahead('SEQ_DEPOSIT_ACCOUNT_PRICING_OVERRIDE','DEPOSIT_ACCOUNT_PRICING_OVERRIDE','ACCOUNT_PRICING_OVERRIDE_ID')); chk('tax exemption sequence ahead',seq_ahead('SEQ_DEPOSIT_TAX_EXEMPTION','DEPOSIT_TAX_EXEMPTION','TAX_EXEMPTION_ID')); chk('tax calculation sequence ahead',seq_ahead('SEQ_DEPOSIT_TAX_CALCULATION','DEPOSIT_TAX_CALCULATION','TAX_CALCULATION_ID')); chk('tax certificate sequence ahead',seq_ahead('SEQ_DEPOSIT_TAX_CERTIFICATE','DEPOSIT_TAX_CERTIFICATE','TAX_CERTIFICATE_ID'));
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_ACCOUNT_CONFIRMATION C JOIN DPS2.DEPOSIT_ACCOUNT A ON A.ACCOUNT_ID=C.ACCOUNT_ID WHERE C.CURRENCY_CODE<>A.CURRENCY_CODE; chk('confirmations preserve account currency',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_ACCOUNT_API_ACCESS X LEFT JOIN DPS2.DEPOSIT_ACCOUNT_PARTY P ON P.ACCOUNT_ID=X.ACCOUNT_ID AND P.PARTY_ID=X.AUTHORIZED_PARTY_ID WHERE X.AUTHORIZED_PARTY_ID IS NOT NULL AND P.ACCOUNT_PARTY_ID IS NULL; chk('API authorized party traces to account party',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_ACCOUNT_AUTHORIZED_USER X LEFT JOIN DPS2.DEPOSIT_ACCOUNT_PARTY P ON P.ACCOUNT_ID=X.ACCOUNT_ID AND P.PARTY_ID=X.PARTY_ID WHERE P.ACCOUNT_PARTY_ID IS NULL; chk('authorized users trace to account party',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_ACCOUNT_PAYMENT_INSTRUMENT X LEFT JOIN DPS2.DEPOSIT_ACCOUNT_PARTY P ON P.ACCOUNT_ID=X.ACCOUNT_ID AND P.PARTY_ID=X.HOLDER_PARTY_ID WHERE X.HOLDER_PARTY_ID IS NOT NULL AND P.ACCOUNT_PARTY_ID IS NULL; chk('payment instrument holder traces to account party',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_COMPLIANCE_EVALUATION E JOIN DPS2.DEPOSIT_REGULATORY_RULE R ON R.REGULATORY_RULE_ID=E.REGULATORY_RULE_ID WHERE E.ACCOUNT_ID IS NOT NULL AND E.RESULT_STATUS_CODE NOT IN ('PASS','FAIL','REVIEW','WAIVED'); chk('compliance evaluation result contract coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_ACCOUNT_PRICING_OVERRIDE P LEFT JOIN DPS2.DEPOSIT_OPERATION_APPROVAL_REQUEST A ON A.APPROVAL_REQUEST_ID=P.APPROVAL_REQUEST_ID WHERE P.APPROVAL_REQUEST_ID IS NOT NULL AND (A.APPROVAL_REQUEST_ID IS NULL OR (P.STATUS_CODE='ACTIVE' AND A.APPROVAL_STATUS_CODE<>'APPROVED')); chk('active pricing override has approved maker-checker trace',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_TAX_CALCULATION T LEFT JOIN DPS2.DEPOSIT_TAX_RULE R ON R.TAX_RULE_ID=T.TAX_RULE_ID WHERE R.TAX_RULE_ID IS NULL OR (T.PROFIT_PAYMENT_ID IS NULL AND T.TRANSACTION_ID IS NULL); chk('tax calculations preserve rule and taxable event trace',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_TAX_CERTIFICATE C WHERE C.GROSS_AMOUNT<0 OR C.TAX_AMOUNT<0 OR C.PERIOD_END<C.PERIOD_START; chk('tax certificate values coherent',v=0);
  DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------'); DBMS_OUTPUT.PUT_LINE('PHASE11L_DB_VERIFIER_PASS='||p); DBMS_OUTPUT.PUT_LINE('PHASE11L_DB_VERIFIER_FAIL='||f); IF f>0 THEN RAISE_APPLICATION_ERROR(-21259,'Phase 11L DB verifier failed: '||f); END IF; DBMS_OUTPUT.PUT_LINE('PHASE11L_DB_BASELINE_PASS');
END;
/
